package net.officefloor.hq.app.voidreason;

import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The sheet's void reasons in the order they were added, each with how many VOID claims were voided with it (as
 *  of a date (?asOf=): the claims VOID as the sheet stood at the end of it). */
public class RespondWithVoidReasons {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "asOf", required = false) String asOf, VoidReasonRepository repository,
            ClaimRepository claims, ObjectResponse<List<VoidReasonResponse>> response) {
        String id = sheetId.trim();
        LocalDate end = AsOf.parse(asOf);
        Map<String, Integer> voided = end == null ? repository.voided(id)
                : repository.voided(id, claims.listAsOf(id, end).stream().filter(c -> c.status() == net.officefloor.hq.app.claim.ClaimStatus.VOID)
                        .map(c -> c.id()).collect(Collectors.toSet()));
        response.send(repository.list(id).stream()
                .map(r -> VoidReasonResponse.from(r, voided.getOrDefault(r.reason(), 0))).toList());
    }
}
package net.officefloor.hq.app.voidreason;

import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Store the void reason, refusing one already on the sheet's list. */
public class SaveVoidReason {
    public void save(@PathVariable("sheetId") String sheetId, @Val VoidReasonInput input, PeriodRepository periods,
            VoidReasonRepository repository, Out<VoidReason> reason) throws InvalidVoidReasonException {
        String id = sheetId.trim();
        periods.lockSheet(id);
        if (repository.exists(id, input.reason())) {
            throw new InvalidVoidReasonException(input.reason() + " is already a void reason.");
        }
        reason.set(repository.add(id, input));
    }
}
package net.officefloor.hq.app.voidreason;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: a signed-in user and a reason that is not
 *  blank. */
public class ValidateVoidReason {
    public void validate(@RequestBody VoidReasonRequest request, Out<VoidReasonInput> body)
            throws InvalidVoidReasonException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidVoidReasonException("Sign in before adding a void reason.");
        }
        String reason = request.reason() == null ? "" : request.reason().trim();
        if (reason.isEmpty()) {
            throw new InvalidVoidReasonException("Give the void reason.");
        }
        body.set(new VoidReasonInput(request.user().trim(), reason));
    }
}
