/** Bind the body and refuse it before anything is read or written: a signed-in user and a grade of A, B or C. */
public class ValidateInlineGrade {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody InlineGradeRequest request, Out<InlineGradeRequest> body)
            throws InvalidPersonException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPersonException("Sign in before changing people.");
        }
        String grade = request.grade() == null ? "" : request.grade().trim();
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("The grade must be A, B or C.");
        }
        body.set(new InlineGradeRequest(request.user().trim(), grade, request.version()));
    }
}
package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written. Each non-blank line is name,grade,terms,contact
 *  — the grade may be absent or blank (the sheet's default grade, published as null), the terms and contact absent or blank — and must pass exactly the person form's rules; no two lines may
 *  give the same name, or the same contact (compared as the sheet compares them). A paste with no lines is refused.
 *  A refusal names the first line that fails. */
public class ValidateImport {
    public void validate(@RequestBody ImportRequest request, Out<ImportInput> body) throws InvalidPersonException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPersonException("Sign in before changing people.");
        }
        String user = request.user().trim();
        String[] rows = (request.text() == null ? "" : request.text()).split("\\r?\\n|\\r", -1);
        List<ImportLine> lines = new ArrayList<>();
        Set<String> names = new HashSet<>();
        Set<String> contacts = new HashSet<>();
        for (int i = 0; i < rows.length; i++) {
            if (rows[i].isBlank()) {
                continue;
            }
            int number = i + 1;
            String[] fields = rows[i].split(",", 4);
            try {
                boolean blankGrade = fields.length < 2 || fields[1].isBlank();
                PersonRequest person = ValidatePerson.check(new PersonRequest(user, fields[0],
                        blankGrade ? "A" : fields[1], null, null, fields.length > 2 ? fields[2] : "",
                        fields.length > 3 ? fields[3] : "", null, null));
                if (blankGrade) {
                    person = withGrade(person, null);
                }
                if (!names.add(person.name().toLowerCase(Locale.ROOT))) {
                    throw new DuplicatePersonNameException(person.name());
                }
                if (!person.contact().isEmpty() && !contacts.add(person.contact())) {
                    throw new DuplicatePersonContactException(person.contact());
                }
                lines.add(new ImportLine(number, person));
            } catch (InvalidPersonException | DuplicatePersonNameException | DuplicatePersonContactException e) {
                throw new InvalidPersonException("Line " + number + ": " + e.getMessage());
            }
        }
        if (lines.isEmpty()) {
            throw new InvalidPersonException("Paste at least one line: name,grade,terms,contact.");
        }
        body.set(new ImportInput(user, lines));
    }

    /** The request with the grade given (null: blank, the sheet's default grade). */
    static PersonRequest withGrade(PersonRequest p, String grade) {
        return new PersonRequest(p.user(), p.name(), grade, p.version(), p.gradeFrom(), p.terms(), p.contact(), p.tags(),
                p.termsFrom());
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.LinkedHashSet;
import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read: a signed-in user, at least one selected person, a grade of
 *  A, B or C, and a from-date (optional) that is a real yyyy-mm-dd date. */
public class ValidateBulkGrade {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody BulkGradeRequest request, Out<BulkGradeInput> body) throws InvalidPersonException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPersonException("Sign in before changing people.");
        }
        if (request.personIds() == null || request.personIds().isEmpty()) {
            throw new InvalidPersonException("Select the people to grade.");
        }
        String grade = request.grade() == null ? "" : request.grade().trim();
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("The grade must be A, B or C.");
        }
        String from = request.from() == null ? "" : request.from().trim();
        LocalDate fromDate = null;
        if (!from.isEmpty()) {
            try {
                fromDate = LocalDate.parse(from);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("The grade's from-date must be a date, yyyy-mm-dd.");
            }
        }
        body.set(new BulkGradeInput(request.user().trim(), new LinkedHashSet<>(request.personIds()), grade, fromDate));
    }
}
