# Import people: each line name,grade,terms,contact (the last two may be absent or blank; a blank grade is the sheet's default grade), in order, updates the person on the
# sheet with that name or alias as the form's edit would (grade from the sheet's today; terms and contact when given), or else
# adds a person as the form adds them. Every line is checked first by the person form's rules (and no name or contact repeated
# within the paste); one failing line refuses the whole import, which writes nothing, not even an audit line. Responds with how
# many were added and how many updated.
validate:
  class: net.officefloor.hq.app.person.ValidateImport
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: import
import:
  class: net.officefloor.hq.app.person.ImportPeople
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithImport
  govern: [ transaction ]
# Give the selected people a grade together from a from-date (blank: the sheet's today), in list order. Each is
# graded exactly as the person form's edit would (name and terms kept), with its PERSON_EDITED line and then how the
# sheet's figures moved over it. A refused request (no user, no people, a bad grade or date) writes nothing.
validate:
  class: net.officefloor.hq.app.person.ValidateBulkGrade
  next: grade
grade:
  class: net.officefloor.hq.app.person.BulkGradePeople
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithBulkGrade
  govern: [ transaction ]
