def ins(path, after_step, nxt_orig, cls):
    p=R+path; s=open(p).read()
    # find "after_step:\n  class..\n  govern..\n  next: X"
    m=re.search(r"(^%s:\n(?:  .*\n)*?  next: )(\w+)\n" % after_step, s, re.M)
    assert m, path
    orig=m.group(2)
    gov = "  govern: [ transaction ]\n"
    s=s[:m.start()]+m.group(1)+"grade\n"+s[m.end():]
    # append grade step right after
    idx=s.index("\n", s.index(m.group(1)+"grade"))+1
    s=s[:idx]+"grade:\n  class: net.officefloor.hq.app.grade.%s\n%s  next: %s\n"%(cls,gov,orig)+s[idx:]
    open(p,"w").write(s)
