  await p.getByTestId('rate-form-pct').fill('10.00');
  await p.getByTestId('rate-form-submit').click();
  await p.waitForTimeout(1500);
  console.log('ERR', await p.getByTestId('rate-form-error').textContent().catch(() => 'none'));
